const TAGS = ['test:anxiety','test:bt','test:et','test:fa','test:ma','test:ndt','test:occ','test:ocd','test:ps','test:so'];
const EXCL = ['pst','ps','cus','pt_old'];
const langs = ($input.first().json.languages || []).filter(l => !EXCL.includes(l.lang_iso));
if (!langs.length) throw new Error('no languages returned');
const ids = langs.map(l => l.lang_id).join(',');
return TAGS.map(tag => ({ json: { tag, langs: langs.map(l => l.lang_iso), url: 'https://api.lokalise.com/api2/projects/31393214664f295f94dd86.76792605/keys?include_translations=1&disable_references=1&limit=500&pagination=cursor&filter_tags=' + encodeURIComponent(tag) + '&filter_translation_lang_ids=' + ids } }));

const pages = $input.all(); const errors = []; const byId = {}; let seen = 0, archived = 0;
const langs = $('Expand tags').first().json.langs;
pages.forEach((it, i) => {
  const b = it.json.body || it.json;
  if (!Array.isArray(b.keys)) { errors.push('page ' + i + ': ' + JSON.stringify(it.json).slice(0, 300)); return; }
  for (const k of b.keys) {
    seen++;
    if (k.is_archived) { archived++; continue; }
    if (byId[k.key_id]) continue;
    const kn = k.key_name || {}; const name = kn.web || kn.other || kn.ios || kn.android || String(k.key_id);
    const t = {}, m = {}; let en = '';
    for (const tr of (k.translations || [])) {
      let txt = tr.translation; if (txt && typeof txt === 'object') txt = JSON.stringify(txt);
      if (tr.language_iso === 'en') { en = txt || ''; continue; }
      if (!txt) continue;
      t[tr.language_iso] = txt;
      m[tr.language_iso] = (tr.is_reviewed ? 1 : 0) + '|' + (tr.is_unverified ? 1 : 0) + '|' + (tr.modified_by_email || '');
    }
    byId[k.key_id] = { id: k.key_id, k: name, en, tags: (k.tags || []).filter(x => x.startsWith('test:')), d: k.description || '', t, m };
  }
});
const rows = Object.values(byId);
return [{ json: { pages: pages.length, keys_seen: seen, archived, unique: rows.length, langs, errors, rows } }];

