const FA = 'This string belongs to the FEMALE ARCHETYPE test. The reader is a woman and the archetypes (The Maiden, The Lover, The Nurturer, The Queen, The Warrior, The Sage, The Mystic, The Rebel) are female. Everything referring to the user or the archetype MUST be grammatically FEMININE only. Violations: any masculine form (article, noun, adjective, participle, pronoun, verb agreement) referring to the user or the archetype; any dual/inclusive form such as (e), o/a, (-a), gender star; and an unmarked/masculine archetype noun where a natural feminine form exists in this language (e.g. Dutch "De Krijger" instead of "De Krijgster", Polish "Mędrzec" instead of "Mędrczyni"). The style guide gender-neutrality rule does NOT apply to this test.';
const MA = 'This string belongs to the MALE ARCHETYPE test. The reader is a man and the archetypes (The King, The Warrior, The Lover, The Sage, The Rebel, The Provider, The Explorer, The Craftsman) are male. Everything referring to the user or the archetype MUST be grammatically MASCULINE only. Violations: any feminine form referring to the user or the archetype; any dual/inclusive form such as (e), o/a, (-a), gender star. The style guide gender-neutrality rule does NOT apply to this test.';
const TESTNAME = {'test:anxiety':'Anxiety','test:bt':'Bipolar','test:et':'Empath','test:ndt':'Neurodivergence','test:occ':'Occupation','test:ocd':'OCD','test:ps':'Psychopath','test:so':'Sociopath'};
const rows = $input.first().json.rows;
const out = [];
for (const lang of LANGS) {
  for (const tag of Object.keys(TESTNAME).concat(['test:fa','test:ma'])) {
    const items = rows.filter(r => r.tags.includes(tag) && r.t[lang] && /[A-Za-z]{3}/.test(r.en) && !/^Level \d+$/.test(r.en))
      .map(r => ({ id: r.id, en: r.en, tr: r.t[lang] }));
    let rule;
    if (tag === 'test:fa') rule = FA; else if (tag === 'test:ma') rule = MA;
    else rule = 'This string belongs to the ' + TESTNAME[tag] + ' test, which is for readers of ANY gender. Use gender-neutral language, or follow the language style guide for addressing both genders. ' + NEUTRAL_RULE[lang];
    for (let i = 0; i < items.length; i += 30) {
      const chunk = items.slice(i, i + 30);
      const sys = 'You are a senior ' + NAMES[lang] + ' linguist reviewing translations of a personality-test website for GRAMMATICAL GENDER only. Do not comment on meaning, style, terminology, typos or punctuation. ' + rule + ' Only report genuine gender violations you are sure about; third-person generic references to other people (e.g. "others", "people around you") are not the user. Return JSON: {"findings":[{"id":<id>,"issue":"wrong_gender"|"dual_form"|"gendered_in_neutral"|"masculine_noun_for_female","evidence":"exact offending substring from tr","suggestion":"the full corrected translation","explanation":"one short sentence in English"}]}. Return {"findings":[]} if nothing is wrong.';
      out.push({ json: { lang, tag, n: chunk.length, body: { model: 'gpt-4.1', temperature: 0, response_format: { type: 'json_object' }, messages: [ { role: 'system', content: sys }, { role: 'user', content: JSON.stringify(chunk) } ] } } });
    }
  }
}
return out;

const reqs = $('Build batches').all();
const res = $input.all();
const findings = []; const errors = []; let batches = 0;
res.forEach((it, i) => {
  const meta = reqs[i] ? reqs[i].json : {};
  try {
    const c = it.json.choices[0].message.content;
    const p = JSON.parse(c); batches++;
    for (const f of (p.findings || [])) findings.push(Object.assign({ lang: meta.lang, tag: meta.tag }, f));
  } catch (e) { errors.push({ i, lang: meta.lang, tag: meta.tag, err: String(e), raw: JSON.stringify(it.json).slice(0, 300) }); }
});
return [{ json: { requests: reqs.length, responses: res.length, batches, errors, findings } }];
